const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../calendar_date.cjs');
test('full-date shape and month/year restrictions', () => {
 for (const s of ['2000-02-29','2024-02-29','2025-01-31','2025-04-30','2025-12-31','0001-01-01']) assert.equal(app.validDate(s),true,s);
 for (const s of ['1900-02-29','1800-02-29','2025-02-29','2025-04-31','2025-00-10','2025-13-01','2025-01-00','2025-1-01','2025-01-01\n','２０２５-01-01']) assert.equal(app.validDate(s),false,s);
});

test('project year bounds and every month end', () => {
  for (const s of ['0000-01-01','0000-02-29','10000-01-01','2025-01-32','2025-02-30','2100-02-29']) assert.equal(app.validDate(s),false,s);
  for (const s of ['2400-02-29','9999-12-31']) assert.equal(app.validDate(s),true,s);
  const ends = ['31','28','31','30','31','30','31','31','30','31','30','31'];
  for (let m=1;m<=12;m++) {
    const prefix = `2025-${String(m).padStart(2,'0')}-`;
    assert.equal(app.validDate(prefix+ends[m-1]),true);
    assert.equal(app.validDate(prefix+String(Number(ends[m-1])+1)),false);
  }
});

